// Load and prepare data
var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

// Build pipeline: encode Region, combine features, train with FastTree
var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
    .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age), nameof(CustomerData.Income), nameof(CustomerData.PurchaseHistory), "RegionEncoded"))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.FastTree());

// Use cross-validation for small datasets; switch to TrainTestSplit with larger data
var cvResults = mlContext.BinaryClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3);
var avgAuc = cvResults.Average(r => r.Metrics.AreaUnderRocCurve);
var avgAccuracy = cvResults.Average(r => r.Metrics.Accuracy);
Console.WriteLine($"Cross-validation — Avg AUC: {avgAuc:F4}, Avg Accuracy: {avgAccuracy:F4}");

// Train final model on all data
var model = pipeline.Fit(dataView);

